import java.util.*;

public class MinCostFlow {
    static class Edge {
        int to, cap, cost, rev;
        public Edge(int to, int cap, int cost, int rev) {
            this.to = to;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static final int MAXN = 6000;
    static final int INF = Integer.MAX_VALUE;
    static final long INF_LL = (long)1e18;

    static List<Edge>[] network = new ArrayList[MAXN];
    static int[] dist = new int[MAXN];
    static int[] parent_node = new int[MAXN];
    static int[] parent_edge = new int[MAXN];
    static boolean[] in_queue = new boolean[MAXN];

    static int total_nodes, s, t;

    static void initialize_network(int _nodes, int _source, int _sink) {
        for (int i = 0; i <= _nodes; i++) {
            network[i] = new ArrayList<>();
        }
        total_nodes = _nodes;
        s = _source;
        t = _sink;
    }

    static void connect(int from, int to, int capacity, int cost) {
        network[from].add(new Edge(to, capacity, cost, network[to].size()));
        network[to].add(new Edge(from, 0, -cost, network[from].size() - 1));
    }

    static long find_min_cost_flow(int flow_req) {
        long total_cost = 0;
        while (flow_req > 0) {
            Arrays.fill(dist, 0, total_nodes, INF);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            Arrays.fill(in_queue, 0, total_nodes, false);
            in_queue[s] = true;

            while (!q.isEmpty()) {
                int u = q.poll();
                in_queue[u] = false;
                for (int i = 0; i < network[u].size(); i++) {
                    Edge e = network[u].get(i);
                    if (e.cap > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        parent_node[e.to] = u;
                        parent_edge[e.to] = i;
                        if (!in_queue[e.to]) {
                            in_queue[e.to] = true;
                            q.offer(e.to);
                        }
                    }
                }
            }

            if (dist[t] == INF) return -1;

            int flow_amount = flow_req;
            for (int v = t; v != s; v = parent_node[v]) {
                flow_amount = Math.min(flow_amount, network[parent_node[v]].get(parent_edge[v]).cap);
            }
            flow_req -= flow_amount;
            total_cost += (long) flow_amount * dist[t];
            for (int v = t; v != s; v = parent_node[v]) {
                Edge e = network[parent_node[v]].get(parent_edge[v]);
                e.cap -= flow_amount;
                network[v].get(e.rev).cap += flow_amount;
            }
        }
        return total_cost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        int C = sc.nextInt();
        int D = sc.nextInt();

        int[] A = new int[58];
        List<Integer>[] H = new ArrayList[57];
        for (int i = 0; i < H.length; i++) {
            H[i] = new ArrayList<>();
        }

        for (int i = 1; i <= K; i++) {
            int X = sc.nextInt();
            A[X]++;
        }

        for (int i = 0; i < M; i++) {
            int X = sc.nextInt();
            int Y = sc.nextInt();
            H[X].add(Y);
            H[Y].add(X);
        }

        initialize_network(5103, 0, 5101);
        for (int i = 2; i <= N; i++) {
            connect(0, i, A[i], 0);
        }

        for (int i = 0; i <= 100; i++) {
            for (int l = 1; l <= N; l++) {
                connect(50 * i + l, 50 * (i + 1) + l, K, 0);
                for (int j : H[l]) {
                    for (int k = 1; k <= K; k++) {
                        connect(50 * i + l, 50 * (i + 1) + j, 1, D * (2 * k - 1));
                    }
                }
            }
        }

        for (int i = 1; i <= 101; i++) {
            connect(50 * i + 1, 5101, K, C * i);
        }

        System.out.println(find_min_cost_flow(K));
        sc.close();
    }
}
